  "settings.orphanTracksKept": "{count, plural, one {Збережено {count} трек. Сканування його більше не відвідає: прибрати його можна лише цією дією.} few {Збережено {count} треки. Сканування їх більше не відвідає: прибрати їх можна лише цією дією.} many {Збережено {count} треків. Сканування їх більше не відвідає: прибрати їх можна лише цією дією.} other {Треків збережено: {count}. Сканування їх більше не відвідає: прибрати їх можна лише цією дією.}}",
