  "settings.dangerZone": "Небезпечна зона",
  "settings.cleanupMovedHint": "«Очищення сервера» тепер розташоване в розділі Налаштування › Медіатека, разом з іншими інструментами медіатеки.",
  "settings.cleanupMovedGo": "Відкрити інструменти медіатеки",
  "settings.clearLibraryV2Hint": "Очищає індекс (треки, альбоми, виконавці). Разом із ним буде втрачено: вміст плейлистів, оцінки, закладки, обране, бокс-сети, складені вручну, і редагування альбомів. Жоден музичний файл не видаляється. Безпосередньо перед цим створюється резервна копія бази даних. Сканування поверне лише треки. Щоб оновити медіатеку, краще запустіть повне сканування: воно зберігає бокс-сети й редагування альбомів.",
