  "settings.autoBoxSets": "Автоматичні бокс-сети",
  "settings.autoBoxSetsHint": "Об’єднувати в один альбом диски, розміщені в сусідніх папках (CD1, CD2…), і показувати альбоми з кількох папок у розділі «Бокс-сети». Вимкнено: нічого не об’єднується, а альбом із кількох дисків більше не з’являється в «Бокс-сетах». Уже об’єднані бокс-сети залишаються такими: «Розібрати бокс-сет» на їхній сторінці знову розділяє їх на диски.",
