  "renderer.depthCapNotRate": "Примітка: обмеження розрядності не обмежує частоту дискретизації. Файл 96 kHz/24 біти стає 96 kHz/16 біт — і досі 96 kHz. Якщо ваш рендерер підтримує щонайбільше 48 kHz, також установіть «Макс. частота».",
  "renderer.flacAndWavSplitBySource": "«Примусовий WAV» застосовується лише до джерел, відмінних від FLAC (ALAC, AAC…), — він обходить ALAC-декодер рендерера. Ваші файли FLAC і далі передаються як нативний FLAC.",
  "renderer.wav24Unproven": "Жодна перевірка під час виявлення ще не завершилася успішно: 24 біти залишаються доступними, але ніщо не підтверджує, що цей пристрій може їх відтворювати. Натисніть «Перевірити» вище.",
  "renderer.wav24Refused": "Перевірка під час виявлення показала: цей пристрій не повідомляє ні про audio/L24, ні про audio/wav. 24 біти залишаються недоступними — їх передавання дало б тишу.",
  "renderer.startDelay": "Затримка старту",
