  "renderer.fluxContinu": "Безперервний потік між треками",
  "renderer.fluxContinuHint": "Для плеєрів, які погано з’єднують два послідовні треки: послідовні треки одного формату надсилаються одним потоком WAV без обробки. За першої зміни формату відновлюється звичайне відтворення трек за треком.",
  "renderer.probeFailed": "Не вдалося зчитати можливості рендерера. Сервер не зміг визначити точну причину.",
  "renderer.probeOffline": "Рендерер зараз не виявлено. Переконайтеся, що його ввімкнено і він у тій самій мережі.",
  "renderer.probeEmptySink": "Рендерер відповів, але не опублікував придатних аудіоможливостей. Відтворення все одно може працювати з автоматичними налаштуваннями.",
  "renderer.probeSoapFailed": "Рендерер виявлено, але запит можливостей не вдався. Спробуйте ще раз; якщо він уже відтворює, змінювати мережу не потрібно.",
