  "settings.dlnaCap16bitHint": "Увімкніть, якщо hi-res (24 біти) на цьому рендерері не звучить, а 16 біт працює (Ruark R3). Перекодовує в 16-бітний FLAC замість надсилання 24 біт напряму, які рендерер не може декодувати.",
  "settings.alacPassthroughHint": "Надсилати ALAC на цей рендерер як є (біт-у-біт, без транскодування у FLAC). Вмикайте, лише якщо рендерер нативно декодує ALAC, інакше звуку не буде.",
  "settings.aacPassthroughHint": "Надсилати AAC на цей рендерер як є, замість транскодування у FLAC. Джерело вже стиснене із втратами, тож транскодування не додає якості — воно лише затримує перший звук. Вмикайте, лише якщо рендерер нативно декодує AAC, інакше звуку не буде.",
