  "settings.cloudDisconnected": "Ви вийшли з хмари",
  "settings.signOutConfirm": "Відв'язати цей сервер від облікового запису mozaiklabs.fr? Цей сервер буде від’єднано від облікового запису: його онлайн-копію медіатеки та спільні ресурси в Tune Circle буде видалено, а функції Premium, що надходять з облікового запису, перестануть працювати (ліцензійний ключ залишається активним). Згодом ви зможете увійти знову.",
