  "settings.telemetry": "Телеметрія",
  "settings.telemetryHint": "Надсилати статистику використання для покращення Tune: ідентифікатор екземпляра, версію, платформу, розміри медіатеки, підключені сервіси й моделі пристроїв.",
  "settings.telemetryOffScope": "Вимкнення також припиняє обмін метаданими спільноти та їх завантаження. Перевірка ліцензії продовжує працювати, тож Premium ніколи не втрачається.",
  "settings.communitySync": "Обмін метаданими в спільноті",
  "settings.communitySyncHint": "Долучитися до спільного доповнення даних: зіставлення з MusicBrainz, жанри й дані про учасників запису (композитор, диригент, виконавці), спільні для серверів Tune. Анонімно — ваші файли ніколи не передаються.",
  "settings.cloudListens": "Надсилати мої прослуховування до мого облікового запису",
  "settings.cloudListensHint": "Додає прослуховування з цього сервера на сторінку «Мої прослуховування» вашого облікового запису разом із прослуховуваннями з інших ваших серверів Tune. Для кожного прослуховування: дата, тривалість, непрозорий ідентифікатор профілю, назва, виконавець, альбом і, якщо відомо, ISRC та ідентифікатор MusicBrainz. Ніколи — шляхи до ваших файлів, ваша IP-адреса чи назви зон. Типово вимкнено.",
  "settings.cloudListensLink": "Переглянути мої прослуховування на mozaiklabs.fr",
  "settings.cloudListensConsentTitle": "Ділитися своїми прослуховуваннями з обліковим записом mozaiklabs.fr?",
  "settings.cloudListensConsentIntro": "Tune може додавати прослуховування з цього сервера до вашого облікового запису mozaiklabs.fr. Нічого не надсилається, доки ви не відповісте.",
  "settings.cloudListensConsentSentLabel": "Що надсилається:",
  "settings.cloudListensConsentSent": "для кожного прослуховування — дата, тривалість, назва, виконавець, альбом, непрозорий ідентифікатор профілю і, якщо відомо, ідентифікатори ISRC та MusicBrainz.",
  "settings.cloudListensConsentNeverLabel": "Що ніколи не надсилається:",
  "settings.cloudListensConsentNever": "шляхи до ваших файлів, ваша IP-адреса, назви ваших зон і назви ваших профілів.",
  "settings.cloudListensConsentBenefit": "Що ви отримуєте: сторінку «Мої прослуховування», яка об’єднує прослуховування з усіх ваших серверів Tune, а також прослуховування спільноти.",
  "settings.cloudListensConsentSettingsReminder": "Ви можете будь-коли змінити рішення в розділі Налаштування › Система.",
  "settings.cloudListensConsentError": "Не вдалося зберегти вашу відповідь. Спробуйте ще раз.",
  "settings.cloudListensConsentNo": "Ні",
  "settings.cloudListensConsentYes": "Так, ділитися",
  "settings.cloudListensConsentClose": "Закрити без відповіді",
  "settings.communityShare": "Ділитися моїми оцінками й прослуховуваннями зі спільнотою (анонімно)",
  "settings.communityShareHint": "Окремо від «Моїх прослуховувань», типово вимкнено. Ваші оцінки альбомів (без коментарів) і прослуховування, які ваш обліковий запис отримає ПІСЛЯ ввімкнення, потрапляють до публічних анонімних підсумків, що відображаються на сторінці альбому, коли є щонайменше три різні особи. Жодні індивідуальні дані не показуються. Вимкнення одразу прибирає ваш внесок.",
  "settings.communityMeasuresReceive": "Отримувати результати аналізу від спільноти",
  "settings.communityMeasuresReceiveHint": "Типово вимкнено. Для ваших файлів FLAC сервер запитує в mozaiklabs.fr значення ReplayGain, динамічного діапазону й акустичні відбитки, уже виміряні для точно такого самого сигналу щонайменше двома іншими інсталяціями. Вони лише заповнюють те, чого бракує: ваші теги та власні вимірювання ніколи не замінюються. Сайт отримує лише короткий префікс, ніколи — список ваших файлів.",
  "settings.communityMeasuresContribute": "Ділитися моїми результатами аналізу зі спільнотою",
  "settings.communityMeasuresContributeHint": "Типово вимкнено. Сервер надсилає на сайт лише ті вимірювання, які зробив сам для ваших файлів FLAC (ReplayGain, динамічний діапазон, акустичний відбиток), ідентифіковані за сигнатурою їхнього сигналу. Жодних шляхів, назв, імен файлів чи облікових записів не надсилається: сервер ідентифікується за номером своєї інсталяції. Вимкнення стирає те, що було надіслано.",
  "library.communityRating": "★ {average} (оцінок: {count})",
