  "outputModule.notLinkedTitle": "Модуль {module} встановлено, але він неактивний.",
  "outputModule.notLinkedBody": "Це не проблема встановлення, і ваш ліцензійний ключ тут ні до чого. Права на платні модулі прив’язані до вашого облікового запису Mozaiklabs, а не до ліцензійного ключа: доки до цього сервера не прив’язано обліковий запис, модуль не може отримати свої права й не показуватиме жодного пристрою. Прив’яжіть обліковий запис у розділі Налаштування ▸ Система ▸ Cloud.",
