  "v2.set.peakMeter": "Піковий індикатор",
  "v2.set.peakMeterHint": "Лише відображення — сигнал не змінюється. Панель відтворення показує тільки лампи: дві шкали для неї заширокі.",
  "v2.set.barVu": "Панель відтворення з VU-метрами",
  "v2.set.barVuHint": "Лише відображення — сигнал не змінюється. Два стрілкові індикатори обабіч елементів керування; вони замінюють пікові лампи й міні-спектр. На вузькій панелі повертається звичайна.",
  "v2.set.barOnde": "Смуга перебігу у вигляді хвилі",
  "v2.set.barOndeHint": "Лише відображення. Смуга перебігу на екрані «Зараз грає» та на панелі відтворення малює хвильову форму треку: відтворену частину кольором, решту — приглушено. Для треків медіатеки, а також для Qobuz і TIDAL з параметром нижче; радіо та інші потоки зберігають звичайну смугу.",
  "v2.set.ondeStreaming": "Хвильова форма для стримінгових треків",
  "v2.set.ondeStreamingHint": "Qobuz і TIDAL: після 30 с прослуховування сервер один раз завантажує трек, щоб обчислити його хвильову форму, і зберігає її. Якщо вимкнено, ці треки мають звичайну смугу й нічого не завантажується. Потрібна смуга перебігу у вигляді хвилі.",
  "v2.set.barViz": "Візуалізатор на панелі відтворення",
  "v2.set.barVizHint": "Показувати маленький смуговий візуалізатор (спектр) праворуч на панелі відтворення, поруч із сердечком. Лише відображення: звук не змінюється.",
  "v2.set.peakOff": "Немає",
  "v2.set.peakLamps": "Лампи",
  "v2.set.peakDat": "DAT PCM-7030",
  "v2.set.peakIec": "IEC 268-18",
  "v2.hint.startupView": "Екран, з якого відкривається Tune. Більше нічого не змінюється.",
  "v2.hint.defaultZone": "Зона, вибрана під час запуску, якщо жодну не вибрано. Трек, запущений не задумуючись, піде саме туди.",
  "v2.hint.volumeDisplay": "Як записується гучність. Децибели показують реальне підсилення; відсотки — це шкала відображення, а не вимірювання.",
  "v2.hint.ingestMode": "🔴 «Перемістити» прибирає файл з початкового місця. «Копіювати» залишає його там і займає вдвічі більше місця.",
  "v2.hint.audioBackend": "Драйвер, через який виводиться звук. Для ASIO потрібен драйвер від виробника; без нього вихід залишається беззвучним.",
  "v2.hint.wasapiMode": "В ексклюзивному режимі Tune займає звукову карту лише для себе: потік виходить біт-у-біт (bit-perfect), але інші застосунки замовкають.",
  "v2.hint.replayGainPreamp": "Зсув, що застосовується понад ReplayGain. Підвищення рівня наближає піки до перевантаження — саме для цього й потрібен захист від кліпінгу.",
  "v2.hint.replayGainPreventClipping": "Знижує підсилення рівно настільки, щоб жоден пік не перевищив межу. Без цього додатний попередній підсилювач може перевантажити й без того гучний трек.",
