  "bitperfect.refused": "Суворий біт-у-біт: у відтворенні відмовлено — вихід не може відтворити {requested} kHz без перетворення (він працює на {device} kHz). Вимкніть «Суворий біт-у-біт (bit-perfect)» у налаштуваннях зони, щоб відтворювати з перетворенням.",
