  "v2.set.devialetAirWarning": "Для підсилювачів Devialet Expert першого покоління (D200, D400…), які приймають лише протокол AIR. Цей протокол відтворено зворотною розробкою: він не задокументований і не схвалений Devialet і ще не випробуваний на підсилювачі. Ви вмикаєте його на власний ризик; починайте з вимкненим звуком на підсилювачі.",
