  "cloudBackup.title": "Резервне копіювання в хмару",
  "cloudBackup.intro": "Tune зберігає ваші персональні налаштування в Mozaiklabs, зашифровані на цьому сервері ключем, якого Mozaiklabs не знає: налаштування, зони, профілі та вподобання, еквалайзери, обране, плейлисти й радіостанції. Ніколи не вашу медіатеку і не паролі чи токени сервісів, за одним винятком: токен Discogs, який передається зашифрованим разом з усім іншим. Зберігається щонайбільше три знімки на машину й п’ять машин на обліковий запис; найстаріші видаляються.",
