  "upsampling.eyebrow": "Плагін Premium",
  "upsampling.title": "Передискретизація",
  "upsampling.lead": "Підвищує частоту джерела до найвищої частоти, яку приймає ЦАП, у межах її сімейства (44.1 → 352.8 kHz, 48 → 384 kHz), на локальному виході. Рівень знижується на 3 dB, а захисний лімітер стримує рідкісні піки, що залишилися: жодного кліпінгу. Ці 3 dB повертає регулятор гучності Tune: рівень дорівнює відтворенню без передискретизації, доки гучність на рівні −3 dB або нижче (на 100% рівень регулюється на ЦАП або попередньому підсилювачі).",
  "upsampling.noZone": "Виберіть зону, щоб налаштувати її передискретизацію.",
  "upsampling.bitPerfect": "Коли передискретизація активна, вона змінює кожен семпл: шлях більше не біт-у-біт (bit-perfect). Режим PURE завжди її обходить, а потік DoP ніколи не передискретизується.",
  "upsampling.enabled": "Передискретизувати цю зону",
  "upsampling.enabledHint": "За замовчуванням вимкнено. Лише локальний вихід, на ЦАП із виміряними частотами. У macOS і Windows — лише в спільному режимі (не в ексклюзивному й не через ASIO); у Linux — також із прямим виходом hw:. Нативний DSD і повністю декодовані стиснуті потоки не передискретизуються.",
  "upsampling.filter": "Фільтр",
  "upsampling.filterHint": "Пропонуються лише фільтри, які ця машина виконує в реальному часі (із запасом ×3). У дужках — зниження рівня.",
  "upsampling.filterNotAdmitted": "Ця машина не може виконувати цей фільтр у реальному часі: його не буде застосовано. Виберіть інший або виміряйте машину ще раз.",
  "upsampling.target": "Цільова частота",
  "upsampling.targetHint": "Ціле кратне частоти джерела, ніколи не вище за те, що приймає ЦАП.",
  "upsampling.targetMax": "Максимум ЦАП",
  "upsampling.dither": "Дизеринг",
  "upsampling.ditherHint": "Власний дизеринг виходу під час зменшення розрядності: TPDF, без формування шуму.",
  "upsampling.machine": "Тест машини",
  "upsampling.machineResult": "Фільтрів, які ця машина виконує в реальному часі: {admitted} із {total}.",
  "upsampling.machineNone": "Ще не виміряно: вимірювання виконується під час першого збереження (кілька секунд).",
  "upsampling.remeasure": "Виміряти машину ще раз",
  "upsampling.nextTrack": "Збережено: налаштування застосується до наступного потоку.",
  "upsampling.appliesLater": "Налаштування застосовується до наступного потоку.",
  "upsampling.saved": "Збережено.",
  "upsampling.appliesNow": "Налаштування застосовується одразу: відтворення продовжиться з тієї самої позиції приблизно після секунди тиші.",
  "upsampling.applied": "Застосовано.",
  "upsampling.appliedRestart": "Застосовано: відтворення продовжується з тієї самої позиції.",
  "upsampling.save": "Зберегти",
  "upsampling.constraint.premium": "Передискретизація входить до Tune Premium: ваші налаштування збережено, вони застосуються з Premium.",
  "upsampling.constraint.notInstalled": "Установіть плагін «Передискретизація» в розділі «Розширення», щоб застосувати її.",
  "upsampling.constraint.pure": "Для цієї зони ввімкнено режим PURE: передискретизація обходиться.",
  "upsampling.constraint.machineTest": "Машину ще не виміряно: збережіть або виміряйте ще раз, щоб застосувати.",
  "upsampling.constraint.zoneNotSupported": "Ця зона не виводить звук через локальний вихід машини: передискретизація до неї не застосовується.",
  "upsampling.constraint.strictBitPerfect": "Для цієї зони ввімкнено суворий біт-у-біт: він відхиляє будь-яке перетворення частоти, тож передискретизація не застосовується. Вимкніть його в налаштуваннях зони, щоб передискретизувати.",
  "upsampling.filter.polyvalent": "Універсальний (аподизуючий, лінійна фаза)",
