  "fiche.section.waveform": "Хвильова форма",
  "fiche.waveform.help": "Щоб перевірити сигнал у найгучніших місцях: піки, кліпінг і компресію. Кліпінг зараховується, коли щонайменше три семпли поспіль залишаються на повній шкалі: найімовірніше, сигнал було обрізано. Одиночний пік, що торкається 0 dBFS (нормалізований трек), не враховується. Пік-фактор — це різниця між піком і середнім рівнем (незважений RMS): що він менший, то сильніше стиснута музика. Це не PLR за EBU, який вимірюється в LUFS.",
