  "nowplaying.eqPureNotice": "Для цієї зони ввімкнено режим PURE: сигнал передається без змін, без жодної обробки. Пресети нижче не діятимуть, доки ввімкнено режим PURE.",
  "settings.fixedSampleRate": "Фіксована частота дискретизації виходу",
  "settings.fixedSampleRateOff": "Вимкнено",
  "settings.fixedSampleRateHint": "Застосовується з наступного треку, навіть для джерел з іншого сімейства частот. Не діє в режимі PURE або суворому біт-у-біт. Якщо значення перевищує межу виходу, Tune застосовує цю межу й показує її в шляху сигналу.",
  "settings.zoneExclusiveMode": "Ексклюзивний режим зони",
