  "settings.zoneExclusiveOff": "Спільний",
  "settings.zoneExclusiveHint": "Лише для локального пристрою цієї зони. В ексклюзивному режимі Tune — єдиний застосунок, що використовує пристрій; у спільному режимі інші застосунки зберігають свій звук. Застосовується одразу, якщо нічого не відтворюється, інакше — після завершення поточного відтворення.",
  "settings.zoneExclusivePending": "Ще не застосовано: вихід зберігає свій режим до завершення поточного відтворення, або драйвер нав’язує власний (ASIO).",
  "settings.wasapiPeriod": "Період WASAPI в ексклюзивному режимі",
  "settings.wasapiPeriodAuto": "Авто (період драйвера)",
  "settings.wasapiPeriodHint": "Тривалість кожного буфера, що надсилається на пристрій в ексклюзивному режимі (Windows). Авто підходить для більшості ЦАП. Якщо звук час від часу перескакує з USB-ЦАП («як платівка, що перескакує»), спробуйте 50 мс. Застосовується з наступного запущеного треку; якщо драйвер відхиляє значення, Tune повертається до періоду драйвера.",
  "zone.pauseThisZone": "Призупинити {name}",
  "pareFeu.titre": "Брандмауер Windows фільтрує Tune у цій мережі",
  "pareFeu.corps": "Активну мережу класифіковано як {profils}, і правило брандмауера для Tune її не охоплює. Тому виявлення пристроїв UPnP/DLNA і доступ із телефона заблоковано: пристрій може з’являтися лише як AirPlay або нічого не отримувати.",
  "pareFeu.etapePrive": "Зробіть мережу приватною: Параметри Windows ▸ Мережа й Інтернет ▸ властивості мережі ▸ Профіль мережі: Приватна.",
  "pareFeu.etapeAutoriser": "Або дозвольте Tune в цій мережі: Безпека Windows ▸ Брандмауер і захист мережі ▸ Дозволити роботу програми через брандмауер ▸ tune-server.exe.",
  "pareFeu.etapeRedemarrer": "Потім перезапустіть Tune.",
  "pareFeu.profilDomaine": "Доменна",
  "pareFeu.profilPrive": "Приватна",
  "pareFeu.profilPublic": "Загальнодоступна",
  "pareFeu.corpsBlocage": "Правило брандмауера блокує tune-server.exe у цій мережі ({profils}): {regles}. Воно має перевагу над дозволом, позначеним у «Дозволити роботу програми через брандмауер», де воно не відображається. Тому виявлення пристроїв UPnP/DLNA і доступ із телефона залишаються заблокованими.",
  "pareFeu.etapeSupprimerBlocage": "Видаліть усі правила блокування з назвою {regles} (часто їх два: TCP і UDP): Брандмауер Windows Defender ▸ Додаткові параметри ▸ Правила для вхідних підключень ▸ правила зі значком блокування ▸ Видалити.",
  "pareFeu.corpsAutreChemin": "Tune дозволено в брандмауері, але для іншого розташування, ніж у запущеної програми. Тому в цій мережі ({profils}) виявлення пристроїв UPnP/DLNA і доступ із телефона заблоковано.",
